  'Content must fit within {size} KB.': { zh: '正文不能超过 {size} KB。', 'zh-TW': '內文不能超過 {size} KB。', de: 'Der Inhalt darf höchstens {size} KB groß sein.', es: 'El contenido debe ocupar {size} KB como máximo.', fr: 'Le contenu ne doit pas dépasser {size} KB.', hu: 'A tartalom legfeljebb {size} KB lehet.', nl: 'Inhoud mag maximaal {size} KB zijn.', br: 'O conteúdo deve ter no máximo {size} KB.', cs: 'Obsah může mít nejvýše {size} KB.', pl: 'Treść może mieć maksymalnie {size} KB.', ru: 'Размер содержимого не должен превышать {size} KB.', it: 'Il contenuto non deve superare {size} KB.', ar: 'يجب ألا يتجاوز حجم المحتوى {size} KB.', et: 'Sisu võib olla kuni {size} KB.', sk: 'Obsah môže mať najviac {size} KB.', tr: 'İçerik en fazla {size} KB olabilir.', az: 'Məzmun ən çoxu {size} KB ola bilər.', id: 'Konten tidak boleh melebihi {size} KB.', ja: '本文は {size} KB 以内に収めてください。', ko: '본문은 {size} KB 이내여야 합니다.', th: 'เนื้อหาต้องมีขนาดไม่เกิน {size} KB', uk: 'Розмір вмісту не може перевищувати {size} KB.', gr: 'Το περιεχόμενο πρέπει να χωρά σε {size} KB.', sv: 'Innehållet får vara högst {size} KB.', vi: 'Nội dung không được vượt quá {size} KB.', ca: 'El contingut no pot superar els {size} KB.' },
