  'Invalid sort order.': { zh: '排序方式无效。', 'zh-TW': '排序方式無效。', de: 'Ungültige Sortierung.', es: 'Orden no válido.', fr: 'Ordre de tri invalide.', hu: 'Érvénytelen rendezési sorrend.', nl: 'Ongeldige sorteervolgorde.', br: 'Ordem de classificação inválida.', cs: 'Neplatné řazení.', pl: 'Nieprawidłowa kolejność sortowania.', ru: 'Недопустимый порядок сортировки.', it: 'Ordinamento non valido.', ar: 'ترتيب الفرز غير صالح.', et: 'Vigane sortimisjärjestus.', sk: 'Neplatné zoradenie.', tr: 'Geçersiz sıralama.', az: 'Sıralama etibarsızdır.', id: 'Urutan tidak valid.', ja: '並べ替え順が無効です。', ko: '올바르지 않은 정렬 순서입니다.', th: 'ลำดับการจัดเรียงไม่ถูกต้อง', uk: 'Недійсний порядок сортування.', gr: 'Μη έγκυρη σειρά ταξινόμησης.', sv: 'Ogiltig sorteringsordning.', vi: 'Thứ tự sắp xếp không hợp lệ.', ca: 'Ordre no vàlid.' },
