export function localeOf(value?: string): TrekLocale {
  const locale = (value || 'en').toLowerCase();
  if (locale.startsWith('zh-tw') || locale.startsWith('zh-hant')) return 'zh-TW';
  if (locale.startsWith('zh')) return 'zh';
  if (locale.startsWith('pt') || locale.startsWith('br')) return 'br';
  if (locale.startsWith('el') || locale.startsWith('gr')) return 'gr';
  const code = locale.slice(0, 2);
  return (LOCALES as readonly string[]).includes(code) ? code as TrekLocale : 'en';
}

export function translate(key: string, locale: string | undefined, zhFallback = key, vars?: Vars): string {
  const language = localeOf(locale);
  const text = messages[key]?.[language] || (language === 'zh' || language === 'zh-TW' ? zhFallback : key);
  return vars ? text.replace(/\{(\w+)\}/g, (match, name: string) => (name in vars ? String(vars[name]) : match)) : text;
}
